43	// BuildEventPayload constructs the event payload for tracking.
44	// Exported for testing. Returns nil if the payload cannot be built.
45	func BuildEventPayload(cmd *cobra.Command, agent string, isEntireEnabled bool, version string) *EventPayload {
46		if cmd == nil {
47			return nil
48		}
49	
50		// Get machine ID for distinct_id
51		machineID, err := machineid.ProtectedID("entire-cli")
52		if err != nil {
53			return nil
54		}
55	
56		// Collect flag names (not values) for privacy
57		var flags []string
58		cmd.Flags().Visit(func(flag *pflag.Flag) {
59			flags = append(flags, flag.Name)
60		})
61	
62		selectedAgent := agent
63		if selectedAgent == "" {
64			selectedAgent = "auto"
65		}
66	
67		properties := map[string]any{
68			"command":         cmd.CommandPath(),
69			"agent":           selectedAgent,
70			"isEntireEnabled": isEntireEnabled,
71			"cli_version":     version,
72			"os":              runtime.GOOS,
73			"arch":            runtime.GOARCH,
74		}
75	
76		if len(flags) > 0 {
77			properties["flags"] = strings.Join(flags, ",")
78		}
79	
80		return &EventPayload{
81			Event:      "cli_command_executed",
82			DistinctID: machineID,
83			Properties: properties,
84			Timestamp:  time.Now(),
85		}
86	}
