160	// SendEvent processes an event payload in the detached subprocess.
161	// This is called by the hidden __send_analytics command.
162	func SendEvent(payloadJSON string) {
163		var payload EventPayload
164		if err := json.Unmarshal([]byte(payloadJSON), &payload); err != nil {
165			return
166		}
167	
168		// Create PostHog client - no need for fast timeouts since we're detached
169		// Read API key and endpoint from package-level vars (not passed via argv for security)
170		client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
171			Endpoint:     PostHogEndpoint,
172			Logger:       silentLogger{},
173			DisableGeoIP: posthog.Ptr(true),
174		})
175		if err != nil {
176			return
177		}
178		defer func() {
179			_ = client.Close()
180		}()
181	
182		// Resolve the installed git version best-effort. A missing or failing
183		// git must never block the rest of the telemetry — the property is simply
184		// omitted when it can't be determined.
185		if v := gitVersion(context.Background()); v != "" {
186			if payload.Properties == nil {
187				payload.Properties = map[string]any{}
188			}
189			payload.Properties["git_version"] = v
190		}
191	
192		// Build properties
193		props := posthog.NewProperties()
194		for k, v := range payload.Properties {
195			props.Set(k, v)
196		}
197	
198		//nolint:errcheck // Best effort telemetry - don't block on result
199		_ = client.Enqueue(posthog.Capture{
200			DistinctId: payload.DistinctID,
201			Event:      payload.Event,
202			Properties: props,
203			Timestamp:  payload.Timestamp,
204		})
205	}
206	
207	// gitVersion returns the installed git version (e.g. "2.43.0"), best-effort.
208	// It returns "" when git is absent, the command fails or times out, or the
209	// output cannot be parsed — callers must treat "" as "unknown" and move on.
210	func gitVersion(ctx context.Context) string {
211		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
212		defer cancel()
213	
214		out, err := exec.CommandContext(ctx, "git", "--version").Output()
215		if err != nil {
216			return ""
217		}
218		return parseGitVersion(string(out))
219	}
220	
221	// parseGitVersion extracts the version token from `git --version` output, which
222	// looks like "git version 2.43.0" (sometimes with a platform suffix such as
223	// "git version 2.39.3 (Apple Git-146)"). Returns "" if the shape is unexpected.
224	func parseGitVersion(out string) string {
225		fields := strings.Fields(out)
226		if len(fields) < 3 || fields[0] != "git" || fields[1] != "version" {
227			return ""
228		}
229		return fields[2]
230	}
